from pathlib import Path
from hashlib import sha256
roots = [Path('products/services/welfare-tender'), Path('products/services/catalogue-gumroad')]
for root in roots:
    print(root)
    for path in sorted(root.rglob('*')):
        if path.is_file() and (root.name == 'catalogue-gumroad' or any(word in path.name.lower() for word in ('baseline', 'verdict', 'checkpoint', 'retirement'))):
            data = path.read_bytes()
            print(path, len(data), sha256(data).hexdigest())
            if path.suffix == '.json' and any(word in path.name.lower() for word in ('verdict', 'checkpoint')):
                print(data.decode('utf-8')[:1800])
